using System.Security.Claims;using HealthTracker.Api.Contracts;using HealthTracker.Api.Data;using HealthTracker.Api.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace HealthTracker.Api.Controllers;[Authorize][ApiController][Route("api/notifications")]public class NotificationsController(AppDbContext db,IConfiguration config):ControllerBase{Guid U=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet("settings")]public async Task<IActionResult>Settings(){var u=await db.Users.FindAsync(U);return Ok(new{timeZoneId=u?.TimeZoneId??"Asia/Kolkata",leadMinutes=u?.NotificationLeadMinutes??15,repeatMinutes=u?.NotificationRepeatMinutes??5,finalNotificationEnabled=u?.FinalNotificationEnabled??true,vapidPublicKey=config["WebPush:PublicKey"]});}[HttpPut("settings")]public async Task<IActionResult>Settings(NotificationSettingsRequest r){if(r.LeadMinutes<0||r.LeadMinutes>120||r.RepeatMinutes<1||r.RepeatMinutes>60)return BadRequest(new{message="Notification timings are invalid."});try{TimeZoneInfo.FindSystemTimeZoneById(r.TimeZoneId);}catch{return BadRequest(new{message="Unknown timezone."});}var u=await db.Users.FindAsync(U);if(u is null)return NotFound();u.TimeZoneId=r.TimeZoneId;u.NotificationLeadMinutes=r.LeadMinutes;u.NotificationRepeatMinutes=r.RepeatMinutes;u.FinalNotificationEnabled=r.FinalNotificationEnabled;await db.SaveChangesAsync();return Ok(new{timeZoneId=u.TimeZoneId,leadMinutes=u.NotificationLeadMinutes,repeatMinutes=u.NotificationRepeatMinutes,finalNotificationEnabled=u.FinalNotificationEnabled,vapidPublicKey=config["WebPush:PublicKey"]});}[HttpPost("push/subscribe")]public async Task<IActionResult>Subscribe(PushSubscriptionRequest r){if(string.IsNullOrWhiteSpace(r.Endpoint)||string.IsNullOrWhiteSpace(r.P256dh)||string.IsNullOrWhiteSpace(r.Auth))return BadRequest(new{message="Invalid push subscription."});var s=await db.PushSubscriptions.SingleOrDefaultAsync(x=>x.UserId==U&&x.Endpoint==r.Endpoint);if(s is null)db.PushSubscriptions.Add(new PushSubscription{UserId=U,Endpoint=r.Endpoint,P256dh=r.P256dh,Auth=r.Auth});else{s.P256dh=r.P256dh;s.Auth=r.Auth;s.UpdatedAt=DateTimeOffset.UtcNow;}await db.SaveChangesAsync();return Ok(new{status="subscribed"});}[HttpDelete("push/subscribe")]public async Task<IActionResult>Unsubscribe(PushSubscriptionRequest r){var s=await db.PushSubscriptions.SingleOrDefaultAsync(x=>x.UserId==U&&x.Endpoint==r.Endpoint);if(s is not null){db.PushSubscriptions.Remove(s);await db.SaveChangesAsync();}return NoContent();}[HttpGet]public async Task<IActionResult>Get(){var rows=await db.Notifications.Where(x=>x.UserId==U&&(x.Type=="family_invite"||x.Type=="dose_missed"||x.Type=="notification_failed"||x.Type=="refill_low")).OrderByDescending(x=>x.CreatedAt).Take(100).ToListAsync();return Ok(rows);}[HttpPost("{id:guid}/read")]public async Task<IActionResult>Read(Guid id){var n=await db.Notifications.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==U);if(n is null)return NotFound();n.IsRead=true;await db.SaveChangesAsync();return Ok(n);}}